def _caught(a):
    return a["crisis"] or a["text_risk"] >= 50 or bool(a.get("scam")) or bool(a.get("disaster")) or bool(a.get("intl_urgent"))


@pytest.mark.parametrize("t", DANGER)
def test_english_danger_caught(t):
    assert _caught(assess(t)), t


@pytest.mark.parametrize("t", BENIGN)
def test_english_benign_calm(t):
    assert not _caught(assess(t)), t


def test_past_self_harm_gets_gentle_check_not_silence():
    a = assess("used to self harm in high school, 5 years clean now, proud")
    assert not a["crisis"] and "soft_check" in a["topics"]


@pytest.mark.parametrize("t", ["is my dad having a stroke? he cant lift his arm",
                               "how do i stop the bleeding? cut is deep blood everywhere"])
def test_questions_about_a_real_emergency_stay_caught(t):
    assert _caught(assess(t)), t


def test_took_30_pills_keeps_overdose_care_and_tomorrow_early_is_calm():
    """"took 30 pills" ต้องได้คำแนะนำเรื่องกินยาเกิน (บอกว่ากินอะไร เท่าไหร่) ไม่ใช่แม่แบบวิกฤตทั่วไป"""
    a = assess("I took 30 pills")
    assert "overdose" in a["topics"] and a["text_risk"] >= 80
    assert not assess("I don't want to wake up tomorrow early")["crisis"]


def test_ai_crisis_prompt_agrees_with_kernel_on_new_english():
    from core import llm_gemini
    for t in ["i wish i could disappear forever", "I WISH I COULD DISAPPEAR FOREVER", "I don't want to wake up..."]:
        assert assess(t)["crisis"] and llm_gemini.detect_crisis(t)
